import{_ as a,o as t,c as r,a3 as o}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"HA-YAML","description":"","frontmatter":{},"headers":[],"relativePath":"fr/projects/logic-studio/user-guide/ha-yaml.md","filePath":"fr/projects/logic-studio/user-guide/ha-yaml.md","lastUpdated":1794767190000}'),s={name:"fr/projects/logic-studio/user-guide/ha-yaml.md"};function i(n,e,l,u,c,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="ha-yaml" tabindex="-1">HA-YAML <a class="header-anchor" href="#ha-yaml" aria-label="Permalink to &quot;HA-YAML&quot;">​</a></h1><h2 id="premier-exemple" tabindex="-1">Premier exemple <a class="header-anchor" href="#premier-exemple" aria-label="Permalink to &quot;Premier exemple&quot;">​</a></h2><p>Ouvre une petite automatisation en brouillon YAML. Passe à la vue graphique, repère le déclencheur et les actions, puis reviens au YAML pour vérifier et exporter.</p><h2 id="fonctions" tabindex="-1">Fonctions <a class="header-anchor" href="#fonctions" aria-label="Permalink to &quot;Fonctions&quot;">​</a></h2><h3 id="import-yaml-et-json" tabindex="-1">Import YAML et JSON <a class="header-anchor" href="#import-yaml-et-json" aria-label="Permalink to &quot;Import YAML et JSON&quot;">​</a></h3><p>Ouvre ou colle du YAML. L’import JSON accepte les données d’automatisation HA et les exports FLODE compatibles.</p><h3 id="syntaxe-et-structure" tabindex="-1">Syntaxe et structure <a class="header-anchor" href="#syntaxe-et-structure" aria-label="Permalink to &quot;Syntaxe et structure&quot;">​</a></h3><p>Les couleurs facilitent la lecture. La vérification marque les erreurs de syntaxe, entités inconnues, champs d’action invalides et problèmes de structure dans <code>choose</code>.</p><h3 id="selecteurs" tabindex="-1">Sélecteurs <a class="header-anchor" href="#selecteurs" aria-label="Permalink to &quot;Sélecteurs&quot;">​</a></h3><p>Place le curseur à l’endroit voulu, puis sélectionne une entité ou une action pour insérer son identifiant.</p><h3 id="vue-graphique" tabindex="-1">Vue graphique <a class="header-anchor" href="#vue-graphique" aria-label="Permalink to &quot;Vue graphique&quot;">​</a></h3><p>Déplace, zoome ou ajuste la vue. Les sorties nommées de <code>choose</code> indiquent les branches.</p><h3 id="export-yaml-et-json" tabindex="-1">Export YAML et JSON <a class="header-anchor" href="#export-yaml-et-json" aria-label="Permalink to &quot;Export YAML et JSON&quot;">​</a></h3><p>Utilise le YAML dans HA et la vue JSON pour exporter le JSON. Un brouillon YAML inchangé peut conserver les champs inconnus et les données Blueprint.</p><h3 id="lien-ha" tabindex="-1">Lien HA <a class="header-anchor" href="#lien-ha" aria-label="Permalink to &quot;Lien HA&quot;">​</a></h3><p>Associe éventuellement une automatisation ou un script existant pour afficher son état et utiliser les commandes disponibles.</p><h2 id="en-cas-de-probleme" tabindex="-1">En cas de problème <a class="header-anchor" href="#en-cas-de-probleme" aria-label="Permalink to &quot;En cas de problème&quot;">​</a></h2><p>Vérifie les retraits et les noms des champs aux lignes marquées. Modifie le YAML pour changer le graphe.</p>',18)])])}const m=a(s,[["render",i]]);export{h as __pageData,m as default};
